import 'package:flutter_local_notifications/flutter_local_notifications.dart';import 'package:timezone/data/latest.dart' as tzdata;import 'package:timezone/timezone.dart' as tz;
class ReminderService{ReminderService._();static final instance=ReminderService._();final _plugin=FlutterLocalNotificationsPlugin();bool _ready=false;
Future<void> initialize()async{if(_ready)return;tzdata.initializeTimeZones();await _plugin.initialize(const InitializationSettings(android:AndroidInitializationSettings('@mipmap/ic_launcher')));_ready=true;}
Future<bool> requestPermission()async{await initialize();final p=_plugin.resolvePlatformSpecificImplementation<AndroidFlutterLocalNotificationsPlugin>();return await p?.requestNotificationsPermission()??false;}
Future<void> scheduleDaily({required int hour,required int minute})async{await initialize();final now=tz.TZDateTime.now(tz.local);var next=tz.TZDateTime(tz.local,now.year,now.month,now.day,hour,minute);if(!next.isAfter(now))next=next.add(const Duration(days:1));await _plugin.zonedSchedule(1001,'A moment with AstroDaily','Your daily reading and reflection are ready.',next,const NotificationDetails(android:AndroidNotificationDetails('astrodaily_daily','Daily reading',channelDescription:'Optional daily reading reminder')),androidScheduleMode:AndroidScheduleMode.inexactAllowWhileIdle,matchDateTimeComponents:DateTimeComponents.time);}
Future<void> cancelDaily()async{await initialize();await _plugin.cancel(1001);}}
